from pysat.solvers import Glucose3
from pysat.card import *
import itertools

# Social Golfers problem: 27 golfers, 7 weeks, 9 groups of 3
num_golfers = 27
num_weeks = 7
num_groups = 9
group_size = 3

# Variables: x[w][p][g] = 1 if golfer p is in group g in week w
# We'll use a SAT encoding

# Let's try a different approach - use constraint programming with backtracking
# or use a more direct encoding

# Actually, let me try using z3 if available
try:
    from z3 import *

    # Create solver
    solver = Optimize()

    # Variables: group[w][p] = group assignment for golfer p in week w (0..8)
    group = [[Int(f'g_{w}_{p}') for p in range(num_golfers)] for w in range(num_weeks)]

    # Constraint 1: Each group variable is in range 0..8
    for w in range(num_weeks):
        for p in range(num_golfers):
            solver.add(group[w][p] >= 0, group[w][p] <= 8)

    # Constraint 2: Each week, each group has exactly 3 golfers
    for w in range(num_weeks):
        for g in range(num_groups):
            solver.add(Sum([If(group[w][p] == g, 1, 0) for p in range(num_golfers)]) == group_size)

    # Constraint 3: No pair of golfers is in the same group more than once
    for p1 in range(num_golfers):
        for p2 in range(p1+1, num_golfers):
            # Count how many weeks they're in the same group
            same_group_count = Sum([If(group[w][p1] == group[w][p2], 1, 0) for w in range(num_weeks)])
            solver.add(same_group_count <= 1)

    print("Solving with Z3...")
    result = solver.check()
    print(f"Result: {result}")

    if result == sat:
        m = solver.model()
        solution = []
        for w in range(num_weeks):
            for p in range(num_golfers):
                solution.append(m[group[w][p]].as_long())
        print(f"Solution found: {solution[:50]}...")
        print(f"Length: {len(solution)}")

        # Verify solution
        # Check each week has valid groups
        for w in range(num_weeks):
            groups = {}
            for p in range(num_golfers):
                g = solution[w*27 + p]
                if g not in groups:
                    groups[g] = []
                groups[g].append(p)
            for g in range(num_groups):
                assert g in groups and len(groups[g]) == 3, f"Week {w}, group {g} invalid"

        # Check no pair appears twice
        pair_weeks = {}
        for w in range(num_weeks):
            for g in range(num_groups):
                golfers_in_group = [p for p in range(num_golfers) if solution[w*27 + p] == g]
                for p1, p2 in itertools.combinations(golfers_in_group, 2):
                    pair = (min(p1, p2), max(p1, p2))
                    assert pair not in pair_weeks, f"Pair {pair} appears in weeks {pair_weeks[pair]} and {w}"
                    pair_weeks[pair] = w

        print("Solution verified!")
        print(solution)
    else:
        print("UNSATISFIABLE")

except ImportError:
    print("Z3 not available, trying alternative approach")

